# Let's verify: W(3,3) = 27 means that any 3-coloring of {1,...,27} contains a monochromatic AP of length 3.
# Therefore, for N=54 >= 27, it's definitely impossible.
# But let me verify by trying to find a valid coloring using SAT.

from pysat.solvers import Glucose3
from pysat.formula import CNF

n = 54
num_colors = 3

# Variables: x[i][c] = 1 if position i has color c (1-indexed positions, 0-indexed colors)
# Variable numbering: var(i, c) = (i-1)*num_colors + c + 1

def var(i, c):
    return (i - 1) * num_colors + c + 1

cnf = CNF()

# Each position gets at least one color
for i in range(1, n + 1):
    cnf.append([var(i, c) for c in range(num_colors)])

# Each position gets at most one color
for i in range(1, n + 1):
    for c1 in range(num_colors):
        for c2 in range(c1 + 1, num_colors):
            cnf.append([-var(i, c1), -var(i, c2)])

# No monochromatic AP of length 3
for a in range(1, n + 1):
    for d in range(1, n + 1):
        if a + 2 * d <= n:
            for c in range(num_colors):
                cnf.append([-var(a, c), -var(a + d, c), -var(a + 2 * d, c)])

solver = Glucose3()
solver.append_formula(cnf)
result = solver.solve()
print(f"Satisfiable: {result}")

if result:
    model = solver.get_model()
    coloring = []
    for i in range(1, n + 1):
        for c in range(num_colors):
            if var(i, c) in model:
                coloring.append(c)
                break
    print(f"Coloring: {coloring}")
